import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas = document.querySelector('#world');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.7));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;

const scene = new THREE.Scene();
scene.background = new THREE.Color('#a9d8e6');
scene.fog = new THREE.FogExp2('#a9d8e6', 0.012);
const camera = new THREE.PerspectiveCamera(72, window.innerWidth / window.innerHeight, 0.1, 150);
camera.rotation.order = 'YXZ';
scene.add(camera);
const hemi = new THREE.HemisphereLight('#e7f6ff', '#58644a', 1.65);
scene.add(hemi);
const sun = new THREE.DirectionalLight('#fff0d1', 2.25);
sun.position.set(-28, 38, 22);
scene.add(sun);

const mats = {};
const blockDefs = [
  { id: 'grass', name: 'Meadow turf', color: '#73945b', top: '#91ad6b', count: 32 },
  { id: 'dirt', name: 'Rich earth', color: '#8b6349', top: '#a47a5b', count: 18 },
  { id: 'stone', name: 'Mossy stone', color: '#7b817a', top: '#9a9d90', count: 12 },
  { id: 'wood', name: 'Cedar log', color: '#8b6844', top: '#b28d5a', count: 16 },
  { id: 'leaves', name: 'Canopy', color: '#557d54', top: '#70966a', count: 12 },
  { id: 'sand', name: 'Warm sand', color: '#d2bd85', top: '#e3d39e', count: 8 },
  { id: 'plank', name: 'Pine planks', color: '#bd9560', top: '#d2ad75', count: 12 }
];
const defById = Object.fromEntries(blockDefs.map(d => [d.id, d]));
function pixelTexture(color, seed) {
  const c = document.createElement('canvas'); c.width = c.height = 32;
  const ctx = c.getContext('2d'); ctx.fillStyle = color; ctx.fillRect(0, 0, 32, 32);
  let s = seed * 931 + 17;
  for (let i = 0; i < 70; i++) {
    s = (s * 16807) % 2147483647;
    const light = s % 2 ? 255 : 0; const alpha = .035 + ((s >> 7) % 9) / 100;
    ctx.fillStyle = light ? `rgba(255,255,255,${alpha})` : `rgba(20,25,18,${alpha})`;
    const x = s % 32, y = (s >> 8) % 32, size = 1 + ((s >> 16) % 3);
    ctx.fillRect(x, y, size, size);
  }
  const t = new THREE.CanvasTexture(c); t.magFilter = THREE.NearestFilter; t.minFilter = THREE.NearestMipmapLinearFilter; t.colorSpace = THREE.SRGBColorSpace; return t;
}
blockDefs.forEach((d, i) => { mats[d.id] = new THREE.MeshStandardMaterial({ map: pixelTexture(d.color, i + 1), roughness: 1, color: '#ffffff' }); });
const cube = new THREE.BoxGeometry(1, 1, 1);
const blockMeshes = {};
const blocks = new Map();
const key = (x, y, z) => `${x},${y},${z}`;
const parseKey = k => k.split(',').map(Number);
const addBlock = (x, y, z, type) => { blocks.set(key(x, y, z), type); };
const removeBlock = (x, y, z) => blocks.delete(key(x, y, z));
const getBlock = (x, y, z) => blocks.get(key(Math.round(x), Math.round(y), Math.round(z)));
const terrainHeight = (x, z) => {
  const r = Math.sqrt(x*x + z*z), island = Math.max(0, 1 - r / 27);
  const waves = Math.sin(x * .27 + z * .13) * 1.05 + Math.cos(z * .31 - x * .1) * .8 + Math.sin((x + z) * .13) * 1.1;
  return Math.floor(-1 + island * 4.6 + waves * (.45 + island * .5));
};
let seed = 19371;
function random() { seed = (seed * 16807) % 2147483647; return (seed - 1) / 2147483646; }
const WORLD = 29;
for (let x = -WORLD; x <= WORLD; x++) for (let z = -WORLD; z <= WORLD; z++) {
  const radius = Math.hypot(x, z);
  if (radius > 27.5) continue;
  const h = terrainHeight(x, z);
  const shore = radius > 22;
  for (let y = -5; y <= h; y++) {
    const type = y === h ? (shore ? 'sand' : 'grass') : y >= h - 2 ? 'dirt' : 'stone';
    addBlock(x, y, z, type);
  }
}
// Broad-canopy trees, clustered away from the starting clearing.
for (let i = 0; i < 82; i++) {
  const x = Math.round((random() * 2 - 1) * 23), z = Math.round((random() * 2 - 1) * 23);
  if (Math.hypot(x, z) < 6 || Math.hypot(x, z) > 22 || random() > .78) continue;
  const h = terrainHeight(x, z); if (h < 0 || getBlock(x, h, z) !== 'grass') continue;
  const trunk = 3 + Math.floor(random() * 3);
  for (let y = 1; y <= trunk; y++) addBlock(x, h + y, z, 'wood');
  for (let dy = trunk - 1; dy <= trunk + 2; dy++) {
    const radius = dy === trunk + 2 ? 1 : 2;
    for (let dx = -radius; dx <= radius; dx++) for (let dz = -radius; dz <= radius; dz++) {
      if (Math.abs(dx) === radius && Math.abs(dz) === radius && random() < .58) continue;
      if (!getBlock(x + dx, h + dy, z + dz)) addBlock(x + dx, h + dy, z + dz, 'leaves');
    }
  }
}
// Pale shoreline and a shallow blue inlet.
const water = new THREE.Mesh(new THREE.PlaneGeometry(200, 200), new THREE.MeshStandardMaterial({ color: '#83c7d2', transparent: true, opacity: .46, roughness: .25, metalness: .05 }));
water.rotation.x = -Math.PI / 2; water.position.y = -0.55; scene.add(water);
const oceanBed = new THREE.Mesh(new THREE.PlaneGeometry(200, 200), new THREE.MeshStandardMaterial({ color: '#6faaa6', roughness: 1 }));
oceanBed.rotation.x = -Math.PI / 2; oceanBed.position.y = -1.02; scene.add(oceanBed);
function rebuildWorld() {
  Object.values(blockMeshes).forEach(mesh => { scene.remove(mesh); mesh.dispose?.(); });
  for (const def of blockDefs) {
    const entries = [];
    for (const [k, type] of blocks) if (type === def.id) entries.push(parseKey(k));
    if (!entries.length) continue;
    const mesh = new THREE.InstancedMesh(cube, mats[def.id], entries.length);
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    const dummy = new THREE.Object3D();
    entries.forEach(([x, y, z], i) => { dummy.position.set(x, y, z); dummy.updateMatrix(); mesh.setMatrixAt(i, dummy.matrix); });
    mesh.userData.coords = entries; mesh.userData.type = def.id;
    mesh.castShadow = false; mesh.receiveShadow = true;
    scene.add(mesh); blockMeshes[def.id] = mesh;
  }
}
rebuildWorld();

const outline = new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(1.012, 1.012, 1.012)), new THREE.LineBasicMaterial({ color: '#fff1bb', transparent: true, opacity: .95 }));
outline.visible = false; scene.add(outline);
const raycaster = new THREE.Raycaster(); raycaster.far = 6.2;
const screenCenter = new THREE.Vector2(0, 0);
let target = null;

const player = { x: 0, z: 0, feet: terrainHeight(0, 0) + .5, vy: 0, yaw: Math.PI * .83, pitch: -.12, grounded: false, health: 10, energy: 10 };
const cameraOffset = 1.62;
camera.position.set(player.x, player.feet + cameraOffset, player.z);
let selected = 0;
const inventory = Object.fromEntries(blockDefs.map(d => [d.id, d.count]));
let paused = true, started = false, dayTime = 8, dayNum = 1, toastTimer;
const pressed = new Set();
let discovered = blocks.size;
const $ = s => document.querySelector(s);
const toast = (text) => { const el = $('#toast'); el.textContent = text; el.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('show'), 1650); };
function renderHotbar() {
  $('#hotbar').innerHTML = blockDefs.map((d, i) => `<div class="slot ${i === selected ? 'selected' : ''}" data-slot="${i}"><span class="slot-number">${i + 1}</span><span class="block-icon" style="--block:${d.color};--top:${d.top}"></span><span class="block-count">${inventory[d.id] ?? 0}</span></div>`).join('');
}
function renderVitals() {
  $('#hearts').innerHTML = Array.from({ length: 5 }, (_, i) => `<span class="heart ${player.health < (i + 1) * 2 ? 'empty' : ''}">♥</span>`).join('');
  $('#hunger').innerHTML = Array.from({ length: 5 }, (_, i) => `<span class="energy ${player.energy < (i + 1) * 2 ? 'empty' : ''}">◆</span>`).join('');
}
renderHotbar(); renderVitals();
$('#block-count').textContent = `${discovered.toLocaleString()} BLOCKS DISCOVERED`;

function findTarget() {
  raycaster.setFromCamera(screenCenter, camera);
  const meshes = Object.values(blockMeshes);
  const hit = raycaster.intersectObjects(meshes, false)[0];
  if (!hit || hit.instanceId === undefined) { target = null; outline.visible = false; $('#target-name').textContent = ''; return; }
  const coords = hit.object.userData.coords[hit.instanceId];
  target = { x: coords[0], y: coords[1], z: coords[2], type: hit.object.userData.type, normal: hit.face.normal.clone().transformDirection(hit.object.matrixWorld).round() };
  outline.position.set(target.x, target.y, target.z); outline.visible = true;
  $('#target-name').textContent = defById[target.type].name;
}
function playerWouldOverlap(x, y, z) {
  return Math.abs(x - player.x) < .78 && Math.abs(z - player.z) < .78 && y + .5 > player.feet + .05 && y - .5 < player.feet + 1.82;
}
function interact(button) {
  if (paused || !target) return;
  if (button === 0) {
    if (target.y <= -5) { toast('The bedrock holds fast'); return; }
    const { x, y, z, type } = target;
    removeBlock(x, y, z); inventory[type] = (inventory[type] || 0) + 1; discovered++;
    if (type === 'leaves' && Math.random() < .16) inventory.plank++;
    rebuildWorld(); renderHotbar(); $('#block-count').textContent = `${discovered.toLocaleString()} BLOCKS DISCOVERED`;
    toast(`+1 ${defById[type].name.toUpperCase()}`);
  } else if (button === 2) {
    const def = blockDefs[selected]; if (!inventory[def.id]) { toast(`OUT OF ${def.name.toUpperCase()}`); return; }
    const x = target.x + target.normal.x, y = target.y + target.normal.y, z = target.z + target.normal.z;
    if (getBlock(x, y, z)) return;
    if (playerWouldOverlap(x, y, z)) { toast('A little too close to place'); return; }
    addBlock(x, y, z, def.id); inventory[def.id]--; discovered++;
    rebuildWorld(); renderHotbar(); $('#block-count').textContent = `${discovered.toLocaleString()} BLOCKS DISCOVERED`;
  }
}

function updateCamera() {
  camera.position.set(player.x, player.feet + cameraOffset, player.z);
  camera.rotation.set(player.pitch, player.yaw, 0, 'YXZ');
}
function collisionAt(x, feet, z) {
  const radius = .28;
  const samples = [[-radius, -radius], [radius, -radius], [-radius, radius], [radius, radius], [0, 0]];
  for (const [dx, dz] of samples) {
    const bx = Math.round(x + dx), bz = Math.round(z + dz);
    for (const yy of [feet + .12, feet + .9, feet + 1.68]) if (getBlock(bx, Math.round(yy), bz)) return true;
  }
  return false;
}
function groundAt(x, z, feet) {
  const r = .28; let top = -6;
  for (const [dx, dz] of [[-r,-r],[r,-r],[-r,r],[r,r],[0,0]]) {
    const bx = Math.round(x + dx), bz = Math.round(z + dz);
    for (let by = Math.floor(feet + .55); by >= Math.floor(feet - 1.2); by--) {
      if (getBlock(bx, by, bz)) { top = Math.max(top, by + .5); break; }
    }
  }
  return top;
}
function move(dt) {
  if (paused) return;
  let forward = (pressed.has('KeyW') ? 1 : 0) - (pressed.has('KeyS') ? 1 : 0);
  let sideways = (pressed.has('KeyD') ? 1 : 0) - (pressed.has('KeyA') ? 1 : 0);
  const len = Math.hypot(forward, sideways) || 1; forward /= len; sideways /= len;
  const sprint = pressed.has('ShiftLeft') || pressed.has('ShiftRight');
  const speed = sprint && player.energy > 0 ? 7.4 : 4.7;
  const dx = (Math.sin(player.yaw) * forward + Math.cos(player.yaw) * sideways) * speed * dt;
  const dz = (-Math.cos(player.yaw) * forward + Math.sin(player.yaw) * sideways) * speed * dt;
  if (!collisionAt(player.x + dx, player.feet, player.z)) player.x += dx;
  if (!collisionAt(player.x, player.feet, player.z + dz)) player.z += dz;
  if ((pressed.has('Space')) && player.grounded) { player.vy = 8.2; player.grounded = false; pressed.delete('Space'); }
  player.vy -= 22 * dt;
  let next = player.feet + player.vy * dt;
  if (player.vy <= 0) {
    const floor = groundAt(player.x, player.z, next);
    if (floor >= next && player.feet >= floor - .16) { next = floor; player.vy = 0; player.grounded = true; }
    else player.grounded = false;
  } else if (collisionAt(player.x, next, player.z)) { player.vy = 0; next = player.feet; }
  player.feet = next;
  if (player.feet < -4) { player.x = 0; player.z = 0; player.feet = terrainHeight(0, 0) + .5; player.vy = 0; player.health = Math.max(2, player.health - 2); toast('The island brought you back'); renderVitals(); }
  if (sprint && (forward || sideways)) player.energy = Math.max(0, player.energy - dt * .34); else player.energy = Math.min(10, player.energy + dt * .16);
}

function updateTime(dt) {
  dayTime += dt * .04;
  if (dayTime >= 24) { dayTime -= 24; dayNum++; }
  const hour = Math.floor(dayTime), minute = Math.floor((dayTime % 1) * 60);
  $('#clock').textContent = `DAY ${String(dayNum).padStart(2, '0')} · ${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
  const day = Math.max(0, Math.sin((dayTime / 24) * Math.PI * 2 - Math.PI / 2));
  sun.intensity = .45 + day * 2.1; hemi.intensity = .65 + day * 1.05;
  const sky = new THREE.Color().setRGB(.055 + day * .58, .12 + day * .65, .21 + day * .68);
  scene.background.copy(sky); scene.fog.color.copy(sky); water.material.color.set(day > .1 ? '#83c7d2' : '#425e74');
}
let previous = performance.now(), hudClock = 0;
function animate(now) {
  requestAnimationFrame(animate);
  const dt = Math.min((now - previous) / 1000, .04); previous = now;
  updateTime(dt); move(dt); updateCamera(); findTarget();
  hudClock += dt;
  if (hudClock > .4) { $('#coords').textContent = `X ${Math.round(player.x)}  Y ${Math.round(player.feet)}  Z ${Math.round(player.z)}`; renderVitals(); hudClock = 0; }
