}
requestAnimationFrame(animate);

$('#play-button').addEventListener('click', () => {
  started = true;
  $('#overlay').classList.add('hidden');
  if (canvas.requestPointerLock) canvas.requestPointerLock();
  else { paused = false; }
});
document.addEventListener('pointerlockchange', () => {
  if (!started) return;
  paused = document.pointerLockElement !== canvas;
  $('#pause-badge').classList.toggle('show', paused);
  if (!paused) toast('A peaceful place to begin');
});
canvas.addEventListener('click', () => {
  if (started && paused && !document.pointerLockElement && canvas.requestPointerLock) canvas.requestPointerLock();
});
document.addEventListener('mousemove', e => {
  if (paused || document.pointerLockElement !== canvas) return;
  player.yaw -= e.movementX * .0022;
  player.pitch = THREE.MathUtils.clamp(player.pitch - e.movementY * .0022, -1.48, 1.48);
});
document.addEventListener('keydown', e => {
  if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault();
  pressed.add(e.code);
  if (/^Digit[1-7]$/.test(e.code)) { selected = Number(e.code.slice(5)) - 1; renderHotbar(); }
  if (e.code === 'Space' && !e.repeat) pressed.add('Space');
});
document.addEventListener('keyup', e => pressed.delete(e.code));
window.addEventListener('blur', () => pressed.clear());
document.addEventListener('mousedown', e => { if (!paused && (e.button === 0 || e.button === 2)) interact(e.button); });
document.addEventListener('contextmenu', e => e.preventDefault());
$('#hotbar').addEventListener('click', e => {
  const slot = e.target.closest('[data-slot]'); if (!slot) return;
  selected = Number(slot.dataset.slot); renderHotbar();
});
window.addEventListener('wheel', e => {
  if (paused) return;
  selected = (selected + (e.deltaY > 0 ? 1 : blockDefs.length - 1)) % blockDefs.length;
  renderHotbar();
}, { passive: true });
$('#sound-toggle').addEventListener('click', e => {
  const on = e.currentTarget.dataset.off !== 'true';
  e.currentTarget.dataset.off = String(on); e.currentTarget.textContent = on ? '♫' : '♪';
  toast(on ? 'AMBIENCE IS OFF IN THIS BUILD' : 'AMBIENCE IS OFF IN THIS BUILD');
});
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight; camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

